package app

import "example.com/app/store"

type holder struct{ cli *store.Client }

func run(h holder, raw any) error {
	cli, err := store.New("x")
	if err != nil {
		return err
	}
	_ = h.cli.KV.Get("a")
	_ = (*store.Response)(nil).Header()
	_, txn := store.Begin()
	_ = txn.If(true).Commit()
	return cli.Txn().If(true).Commit()
}

